-- Seed tags read the way people write them: "iphone" becomes "iPhone", "android-phone" becomes
-- "Android phone". UPDATE only, no table rebuild. A tag is renamed only when it was seeded
-- (created_by = 'seed') and its label is exactly an old seed slug, so tags the user or the AI
-- made are left alone, and nothing is renamed onto a label that is already taken in its category.
-- The search index is rebuilt at every launch, so it follows.
UPDATE `tags` SET `label` = 'Laptop' WHERE `label` = 'laptop' AND `created_by` = 'seed' AND NOT EXISTS (SELECT 1 FROM `tags` AS `t2` WHERE `t2`.`category_id` = `tags`.`category_id` AND `t2`.`label` = 'Laptop');--> statement-breakpoint
